async function chargerQuestions() {
  const reponse = await fetch('/api/questions');
  if (!reponse.ok) {
    throw new Error('Erreur ' + reponse.status);
  }
  return reponse.json();
}

async function creerQuestion(titre) {
  const reponse = await fetch('/api/questions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ titre }),
  });
  return reponse.json();
}

async function charger() {
  afficher('Chargement…');
  try {
    const donnees = await chargerQuestions();
    afficherListe(donnees);
  } catch (erreur) {
    afficher('Impossible de charger. Vérifiez votre connexion.');
    afficherBoutonReessayer(charger);
  }
}

